// Third-party notices guarantees — issue #139 ("Generate
// `THIRD-PARTY-NOTICES` + write privacy policy / data residency docs").
//
// These tests encode the acceptance criteria as executable checks so the
// generated file and the CI wiring cannot silently regress:
//
//   1. `tool/generate_third_party_notices.dart` parses the committed
//      `pubspec.lock` into a sorted package list (name, version, source,
//      hosted URL, dependency kind).
//   2. The generator downloads each package's license text from its
//      published pub.dev archive (tar.gz — gzip + tar parsing, GNU
//      longname and pax headers included) and renders a deterministic,
//      alphabetically sorted `THIRD_PARTY_NOTICES.txt`.
//   3. Packages without a resolvable license are rendered with an
//      explicit UNKNOWN marker, never silently dropped.
//   4. The committed `THIRD_PARTY_NOTICES.txt` covers every package in
//      the real `pubspec.lock` and carries the do-not-edit header.
//   5. CI regenerates the file and fails when it is stale.
//   6. `PRIVACY.md` documents the per-vendor data flows, local
//      persistence and the consumer's disclosure duty;
//      `docs/DATA_RESIDENCY.md` maps where data is processed; README
//      links both.
//
// Pure-function tests here are hermetic; the tar fixture uses the system
// `tar` when available and skips otherwise. File-shape tests read the
// committed repo state, not the network, so they stay fast and hermetic
// under `dart test -j 2`.

import 'dart:io';

import 'package:test/test.dart';

import '../tool/generate_third_party_notices.dart'
    show
        LockedPackage,
        archiveUrlFor,
        extractLicenseFiles,
        licenseLabel,
        packageBlock,
        parseLock,
        pickLicenseText,
        renderDocument;

/// A representative slice of the real pubspec.lock shape: a direct main
/// dependency, a direct dev dependency, a transitive dependency, and the
/// trailing `sdks:` section that must be ignored.
const _lockFixture = '''
# Generated by pub
# See https://dart.dev/tools/pub/glossary#lockfile
packages:
  uuid:
    dependency: transitive
    description:
      name: uuid
      sha256: "0123abc"
      url: "https://pub.dev"
    source: hosted
    version: "4.6.0"
  hive_ce:
    dependency: "direct main"
    description:
      name: hive_ce
      sha256: "4567def"
      url: "https://pub.dev"
    source: hosted
    version: "2.19.0"
  build_runner:
    dependency: "direct dev"
    description:
      name: build_runner
      sha256: "89ab012"
      url: "https://pub.dev"
    source: hosted
    version: "2.16.0"
sdks:
  dart: ">=3.13.0 <4.0.0"
''';

const _mitText = '''
MIT License

Copyright (c) 2026 Someone

Permission is hereby granted, free of charge, to any person obtaining a copy
of this software and associated documentation files (the "Software"), to deal
in the Software without restriction.
''';

const _apacheText = '''
                                 Apache License
                           Version 2.0, January 2004
''';

const _bsd3Text = '''
Copyright (c) 2026 Someone. All rights reserved.

Redistribution and use in source and binary forms, with or without
modification, are permitted provided that the following conditions are met:

1. Redistributions of source code must retain the above copyright notice.
2. Redistributions in binary form must reproduce the above copyright notice.
3. Neither the name of the copyright holder nor the names of its contributors
   may be used to endorse or promote products derived from this software.
''';

const _bsd2Text = '''
Copyright (c) 2026 Someone. All rights reserved.

Redistribution and use in source and binary forms, with or without
modification, are permitted provided that the following conditions are met:

1. Redistributions of source code must retain the above copyright notice.
2. Redistributions in binary form must reproduce the above copyright notice.
''';

LockedPackage _pkg(
  String name, {
  String version = '1.0.0',
  String source = 'hosted',
  String? url = 'https://pub.dev',
  String dependency = 'transitive',
}) => LockedPackage(
  name: name,
  version: version,
  source: source,
  hostedUrl: url,
  dependency: dependency,
);

void main() {
  group('parseLock', () {
    test('extracts hosted packages with version, url and dependency kind', () {
      final packages = parseLock(_lockFixture);
      expect(packages, hasLength(3));

      final byName = {for (final p in packages) p.name: p};
      expect(byName.keys, containsAll(<String>['hive_ce', 'uuid']));

      final hive = byName['hive_ce']!;
      expect(hive.version, '2.19.0');
      expect(hive.source, 'hosted');
      expect(hive.hostedUrl, 'https://pub.dev');
      expect(hive.dependency, 'direct main');

      final buildRunner = byName['build_runner']!;
      expect(buildRunner.dependency, 'direct dev');
      expect(buildRunner.version, '2.16.0');
    });

    test('returns packages sorted by name regardless of lock order', () {
      final packages = parseLock(_lockFixture);
      expect(
        packages.map((p) => p.name).toList(),
        orderedEquals(<String>['build_runner', 'hive_ce', 'uuid']),
      );
    });

    test('ignores the sdks section and comment lines', () {
      final packages = parseLock(_lockFixture);
      expect(packages.map((p) => p.name), isNot(contains('dart')));
      expect(packages.map((p) => p.name), isNot(contains('packages')));
    });

    test('parses the real committed pubspec.lock', () {
      final lock = File('pubspec.lock').readAsStringSync();
      final packages = parseLock(lock);
      expect(packages, isNotEmpty);
      expect(
        packages.map((p) => p.name),
        containsAll(<String>['hive_ce', 'yaml', 'uuid', 'zorphy_annotation']),
      );
      // Sorted output for the real lock too.
      final names = packages.map((p) => p.name).toList();
      expect(names, equals([...names]..sort()));
    });
  });

  group('archiveUrlFor', () {
    test('builds the pub.dev archive endpoint', () {
      expect(
        archiveUrlFor('https://pub.dev', 'hive_ce', '2.19.0'),
        'https://pub.dev/api/archives/hive_ce-2.19.0.tar.gz',
      );
    });

    test('tolerates a trailing slash on the hosted URL', () {
      expect(
        archiveUrlFor('https://pub.dev/', 'uuid', '4.6.0'),
        'https://pub.dev/api/archives/uuid-4.6.0.tar.gz',
      );
    });
  });

  group('licenseLabel', () {
    test('recognizes the common licenses verbatim', () {
      expect(licenseLabel(_mitText), 'MIT');
      expect(licenseLabel(_apacheText), 'Apache-2.0');
      expect(licenseLabel(_bsd3Text), 'BSD-3-Clause');
      expect(licenseLabel(_bsd2Text), 'BSD-2-Clause');
    });

    test('falls back to an explicit custom marker', () {
      expect(
        licenseLabel('some bespoke world-wide license'),
        contains('Custom'),
      );
    });
  });

  group('pickLicenseText', () {
    test('prefers the canonical LICENSE over suffixed variants', () {
      final picked = pickLicenseText({
        'LICENSE.md': 'markdown variant',
        'LICENSE': _mitText,
        'NOTICE': 'notice text',
      });
      expect(picked, _mitText);
    });

    test('a vendored subpackage LICENSE cannot override the root one', () {
      final picked = pickLicenseText({
        'lib/src/selectors/test/LICENSE': 'ported test-suite notice',
        'LICENSE': _mitText,
      });
      expect(picked, _mitText);
    });

    test('returns null when the archive ships no license file', () {
      expect(pickLicenseText({'lib/main.dart': 'void main() {}'}), isNull);
      expect(pickLicenseText(const {}), isNull);
    });
  });

  group('extractLicenseFiles', () {
    test('extracts LICENSE from a real tar.gz archive', () async {
      const tarBinary = '/usr/bin/tar';
      if (!File(tarBinary).existsSync()) {
        markTestSkipped('system tar not available');
      }
      final tmp = await Directory.systemTemp.createTemp('notices_tar');
      try {
        Directory('${tmp.path}/lib').createSync(recursive: true);
        File('${tmp.path}/LICENSE').writeAsStringSync(_mitText);
        File('${tmp.path}/lib/main.dart').writeAsStringSync('void main() {}');
        final archive = '${tmp.path}/pkg.tar.gz';
        await Process.run(tarBinary, [
          '--format=ustar',
          '-czf',
          archive,
          '-C',
          tmp.path,
          'LICENSE',
          'lib/main.dart',
        ]);
        final files = await extractLicenseFiles(
          File(archive).readAsBytesSync(),
        );
        expect(files.keys.single, 'LICENSE');
        expect(files['LICENSE'], _mitText);
      } finally {
        tmp.deleteSync(recursive: true);
      }
    });

    test('ignores non-license files inside the archive', () async {
      const tarBinary = '/usr/bin/tar';
      if (!File(tarBinary).existsSync()) {
        markTestSkipped('system tar not available');
      }
      final tmp = await Directory.systemTemp.createTemp('notices_tar2');
      try {
        Directory('${tmp.path}/lib').createSync(recursive: true);
        File('${tmp.path}/lib/main.dart').writeAsStringSync('void main() {}');
        File('${tmp.path}/pubspec.yaml').writeAsStringSync('name: x\n');
        final archive = '${tmp.path}/pkg.tar.gz';
        await Process.run(tarBinary, [
          '--format=ustar',
          '-czf',
          archive,
          '-C',
          tmp.path,
          'lib/main.dart',
          'pubspec.yaml',
        ]);
        final files = await extractLicenseFiles(
          File(archive).readAsBytesSync(),
        );
        expect(files, isEmpty);
      } finally {
        tmp.deleteSync(recursive: true);
      }
    });
  });

  group('rendering', () {
    test('packageBlock carries name, version, source and license text', () {
      final block = packageBlock(
        _pkg('hive_ce', version: '2.19.0'),
        licenseText: _mitText,
      );
      expect(block, contains('hive_ce'));
      expect(block, contains('2.19.0'));
      expect(block, contains('https://pub.dev/packages/hive_ce'));
      expect(block, contains('MIT'));
      expect(block, contains(_mitText));
    });

    test('a package with no resolvable license gets an explicit UNKNOWN '
        'marker, never a silent omission', () {
      final block = packageBlock(_pkg('zorphy_annotation'), licenseText: null);
      expect(block.toUpperCase(), contains('UNKNOWN'));
      expect(
        block,
        contains('https://pub.dev/packages/zorphy_annotation/license'),
      );
    });

    test('non-hosted dependencies are flagged without a fetch', () {
      final block = packageBlock(
        _pkg('local_pkg', source: 'git', url: null),
        licenseText: null,
      );
      expect(block.toUpperCase(), contains('UNKNOWN'));
      expect(block, contains('git'));
    });

    test('document header forbids hand edits and names the generator', () {
      final doc = renderDocument([
        (package: _pkg('hive_ce', version: '2.19.0'), licenseText: _mitText),
        (package: _pkg('uuid', version: '4.6.0'), licenseText: null),
      ]);
      expect(doc.toUpperCase(), contains('DO NOT EDIT'));
      expect(doc, contains('pubspec.lock'));
      expect(doc, contains('tool/generate_third_party_notices.dart'));
    });

    test('document renders packages in the given (sorted) order', () {
      final doc = renderDocument([
        (package: _pkg('aaa_first', version: '1.0.0'), licenseText: _mitText),
        (package: _pkg('zzz_last', version: '2.0.0'), licenseText: _mitText),
      ]);
      expect(
        doc.indexOf('aaa_first 1.0.0'),
        lessThan(doc.indexOf('zzz_last 2.0.0')),
      );
    });
  });

  group('committed repo state (file-shape)', () {
    test(
      'THIRD_PARTY_NOTICES.txt is committed with the do-not-edit header',
      () {
        final file = File('THIRD_PARTY_NOTICES.txt');
        expect(
          file.existsSync(),
          isTrue,
          reason: 'run: dart run tool/generate_third_party_notices.dart',
        );
        final content = file.readAsStringSync();
        expect(content.toUpperCase(), contains('DO NOT EDIT'));
        expect(content, contains('tool/generate_third_party_notices.dart'));
      },
    );

    test('THIRD_PARTY_NOTICES.txt covers every package in pubspec.lock', () {
      final packages = parseLock(File('pubspec.lock').readAsStringSync());
      final content = File('THIRD_PARTY_NOTICES.txt').readAsStringSync();
      for (final p in packages) {
        expect(
          content,
          contains('Package:  ${p.name} ${p.version}'),
          reason: '${p.name} ${p.version} missing from notices',
        );
      }
    });

    test('CI regenerates the notices and fails on staleness', () {
      final pipeline = File(
        '.github/workflows/pipeline.yml',
      ).readAsStringSync();
      expect(pipeline, contains('tool/generate_third_party_notices.dart'));
      final jobStart = pipeline.indexOf('third-party-notices:');
      expect(
        jobStart,
        greaterThanOrEqualTo(0),
        reason: 'pipeline.yml needs a third-party-notices job',
      );
      final jobBody = pipeline.substring(
        jobStart,
        pipeline.indexOf('\n  pana:', jobStart),
      );
      expect(
        jobBody,
        contains('git status --porcelain'),
        reason: 'staleness check must detect a drifted generated file',
      );
    });

    test('README references PRIVACY.md and the notices file', () {
      final readme = File('README.md').readAsStringSync();
      expect(readme, contains('PRIVACY.md'));
      expect(readme, contains('THIRD_PARTY_NOTICES.txt'));
    });

    test('PRIVACY.md documents vendor flows, local persistence, retention '
        'and the consumer duty', () {
      final file = File('PRIVACY.md');
      expect(file.existsSync(), isTrue);
      final content = file.readAsStringSync();
      // Per-vendor coverage (the three wire protocols the llm slice speaks).
      expect(content, contains('Anthropic'));
      expect(content, contains('OpenAI'));
      expect(content, contains('Gemini'));
      // MCP surface.
      expect(content, contains('MCP'));
      // Local persistence + retention.
      expect(content.toLowerCase(), contains('retention'));
      expect(content.toLowerCase(), contains('hive'));
      // Consumer responsibility.
      expect(content.toLowerCase(), contains('consumer'));
      // Retention on local disk + what is logged.
      expect(content, contains('docs/DATA_RESIDENCY.md'));
    });

    test('docs/DATA_RESIDENCY.md exists and maps processing locations', () {
      final file = File('docs/DATA_RESIDENCY.md');
      expect(file.existsSync(), isTrue);
      final content = file.readAsStringSync();
      expect(content, contains('Anthropic'));
      expect(content, contains('OpenAI'));
      expect(content, contains('Gemini'));
      expect(content, contains('GDPR'));
    });
  });
}
